WITH with_prev AS (SELECT *, LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC) AS prev_txn_time FROM transactions), flagged AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_burst FROM with_prev), sessions_transactions AS (SELECT id, account_id, txn_time, is_flagged, SUM(is_new_burst) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT DATE_TRUNC('MONTH', txn_time) AS activity_month, CASE WHEN burst_id >= 6 THEN 'PREMIUM' ELSE 'STANDARD' END AS burst_id_tier, MAX(txn_time) AS last_txn_time, COUNT(DISTINCT id) AS distinct_ids FROM sessions_transactions GROUP BY 1, 2 ORDER BY burst_id_tier ASC NULLS FIRST;
